package com.flippingfriend.companion;
import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;
public class BuyReplacementIntentTransactionRollbackTest{@Test public void injectedCheckpointRollsBack()throws Exception{Path db=Files.createTempDirectory("rollback").resolve("db");try(SqliteStore s=new SqliteStore(db,n->{if("BUY_REPLACEMENT_INTENT_WRITTEN".equals(n))throw new Exception("injected");})){try{s.saveBuyReplacementIntent(BuyReplacementIntentPersistenceTest.intent());fail();}catch(Exception e){assertTrue(e.getMessage().contains("injected"));}}try(SqliteStore s=new SqliteStore(db)){assertTrue(s.buyReplacementIntents().isEmpty());s.saveBuyReplacementIntent(BuyReplacementIntentPersistenceTest.intent());assertEquals(1,s.buyReplacementIntents().size());}}}